    // ─────────── فصل ۱: تولد اسکار ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Birth of Oskar", titlePersian = "تولد اسکار",
        paragraphs = listOf(
            StoryParagraph("I was born in Danzig, in the year 1924, in a small apartment on Labesweg Street, and the first thing I heard was the beating of drums.", "در دانزیگ، در سال ۱۹۲۴، در آپارتمانی کوچک در خیابان لابسوگ زاده شدم و نخستین چیزی که شنیدم صدای طبل بود."),
            StoryParagraph("I do not mean that there were actual drums in the room; I mean that the rhythm of the world itself, the pulse of history, entered my consciousness from the very first moment.", "منظورم این نیست که طبل واقعی در اتاق بود؛ منظورم این است که ریتم خودِ جهان، نبض تاریخ، از همان نخستین لحظه به آگاهی‌ام وارد شد."),
            StoryParagraph("My mother, Agnes, was a beautiful woman with dark hair and sad eyes, and she carried a secret that would shape my entire life.", "مادرم، اگنس، زنی زیبا با موهای تیره و چشمان غمگین بود و رازی را حمل می‌کرد که تمام زندگی‌ام را شکل می‌داد."),
            StoryParagraph("She was a Kashubian, a member of a small Slavic people who had lived on the Baltic coast for centuries, conquered and reconquered by Germans, Poles, and Swedes.", "او کاشوبی بود، عضوی از مردمی کوچک اسلاو که قرن‌ها در ساحل بالتیک زندگی کرده بودند، فتح و دوباره فتح‌شده توسط آلمانی‌ها، لهستانی‌ها و سوئدی‌ها."),
            StoryParagraph("Her family had learned, over the centuries, to survive by adapting, by keeping their heads down, by speaking whatever language was required of them.", "خانواده‌اش در طول قرن‌ها آموخته بودند با سازگاری زنده بمانند، با سر پایین نگه داشتن، با صحبت کردن به هر زبانی که از آن‌ها خواسته می‌شد."),
            StoryParagraph("But my mother did not want to adapt; she wanted to be loved, and she wanted to love, and she wanted a life that was more than mere survival.", "اما مادرم نمی‌خواست سازگار شود؛ می‌خواست دوست داشته شود و می‌خواست عشق بورزد و زندگی‌ای می‌خواست که چیزی بیش از بقای صرف باشد."),
            StoryParagraph("My father, or rather the man I called father, was Alfred Matzerath, a grocer, a member of the Nazi Party, a man of small ambitions and smaller courage.", "پدرم، یا بهتر، مردی که پدر صدایش می‌زدم، آلفرد ماتسرات بود، بقالی، عضو حزب نازی، مردی با جاه‌طلبی کوچک و شجاعت کوچک‌تر."),
            StoryParagraph("Alfred was a Rhinelander, a Catholic, a man who believed in order and respectability and the proper way of doing things.", "آلفرد اهل راینلند بود، کاتولیک، مردی که به نظم و آبرو و شیوه درست انجام کارها باور داشت."),
            StoryParagraph("He had come to Danzig after the First World War, looking for opportunity, and he had found my mother, and he had married her, and he had believed that he was happy.", "پس از جنگ جهانی اول به دانزیگ آمده بود، در جستجوی فرصت و مادرم را یافته بود و با او ازدواج کرده بود و باور داشت خوشحال است."),
            StoryParagraph("But there was another man in our lives, my mother's cousin, Jan Bronski, a Polish post office clerk, a gentle man with soft hands and a sad smile.", "اما مرد دیگری در زندگی‌مان بود، پسرخاله مادرم، یان برونسکی، کارمند پست لهستانی، مردی لطیف با دستان نرم و لبخندی غمگین."),
            StoryParagraph("Jan was, in truth, my real father; my mother loved him, and he loved her, and their love was forbidden and impossible and real.", "یان در حقیقت پدر واقعی من بود؛ مادرم دوستش داشت و او هم دوستش داشت و عشقشان ممنوع و ناممکن و واقعی بود."),
            StoryParagraph("They had loved each other since childhood, since before the war, since before Alfred had come; and they would love each other until my mother's death.", "از کودکی یکدیگر را دوست داشتند، از پیش از جنگ، از پیش از آمدن آلفرد؛ و تا مرگ مادرم یکدیگر را دوست می‌داشتند."),
            StoryParagraph("Alfred Matzerath was a Nazi; Jan Bronski was a Pole; and my mother, caught between them, was a woman who could not choose, who loved one and lived with the other.", "آلفرد ماتسرات نازی بود؛ یان برونسکی لهستانی بود؛ و مادرم که میانشان گرفتار بود، زنی بود که نمی‌توانست انتخاب کند، یکی را دوست داشت و با دیگری زندگی می‌کرد."),
            StoryParagraph("I was born with a fully developed intellect, with the mind of an adult in the body of an infant, and I could hear and understand everything around me from the moment I emerged from the womb.", "با هوشی کاملاً رشد یافته زاده شدم، با ذهن یک بزرگسال در بدن نوزادی و از لحظه‌ای که از رحم بیرون آمدم می‌توانستم هر چیزی در اطرافم را بشنوم و بفهمم."),
            StoryParagraph("I remember the midwife holding me upside down, and I remember the light bulb swinging above me, and I remember thinking, clearly, 'I have seen enough; I want to go back.'", "به یاد می‌آورم قابله مرا وارونه گرفت و به یاد می‌آورم لامپی که بالای سرم تکان می‌خورد و به یاد می‌آورم که فکر کردم، با وضوح: «بس است؛ می‌خواهم بازگردم.»"),
            StoryParagraph("The midwife laughed at my expression, and my mother smiled weakly, and Alfred, standing in the corner, looked confused and slightly embarrassed.", "قابله از حالت صورتم خندید و مادرم ضعیف لبخند زد و آلفرد که در گوشه ایستاده بود گیج و کمی شرمنده به نظر می‌رسید."),
            StoryParagraph("But I did not go back; instead, I made a decision that would define my entire existence: I would stop growing.", "اما بازنگشتم؛ در عوض، تصمیمی گرفتم که تمام وجودم را تعریف می‌کرد: رشد را متوقف می‌کردم."),
            StoryParagraph("I did not make this decision immediately; I made it at the age of three, after observing the world around me carefully, after understanding what it meant to be an adult.", "این تصمیم را بلافاصله نگرفتم؛ در سه سالگی گرفتم، پس از مشاهده دقیق جهان اطرافم، پس از فهمیدن معنای بزرگسال بودن."),
            StoryParagraph("I watched the grown-ups — my mother, my father, Jan Bronski, the customers in Alfred's store, the neighbors, the officials — and I saw what they were.", "بزرگ‌ترها را تماشا کردم — مادرم، پدرم، یان برونسکی، مشتریان مغازه آلفرد، همسایه‌ها، مقامات — و دیدم چه هستند."),
            StoryParagraph("I saw that they lied, and cheated, and pretended; I saw that they said one thing and did another; I saw that they believed in things they did not understand.", "دیدم دروغ می‌گویند و تقلب می‌کنند و تظاهر می‌کنند؛ دیدم چیزی می‌گویند و دیگری می‌کنند؛ دیدم به چیزهایی باور دارند که نمی‌فهمند."),
            StoryParagraph("I saw that they were unhappy, mostly, and that they did not know why; I saw that they were afraid, mostly, and that they did not know of what.", "دیدم بیشترشان ناخوشحالند و نمی‌دانند چرا؛ دیدم بیشترشان می‌ترسند و نمی‌دانند از چه."),
            StoryParagraph("And I saw that they were preparing for something terrible — for a war, for a catastrophe, for a destruction that they could not imagine and could not prevent.", "و دیدم خودشان را برای چیزی هولناک آماده می‌کنند — برای جنگی، برای فاجعه‌ای، برای نابودی‌ای که نمی‌توانستند تصورش کنند و نمی‌توانستند جلویش را بگیرند."),
            StoryParagraph("And I decided, at the age of three, that I did not want to become one of them; I did not want to grow up into an adult who lied and cheated and pretended.", "و در سه سالگی تصمیم گرفتم نمی‌خواهم یکی از آن‌ها شوم؛ نمی‌خواهم به بزرگسالی تبدیل شوم که دروغ می‌گوید و تقلب می‌کند و تظاهر می‌کند."),
            StoryParagraph("I fell down the cellar stairs, deliberately, on purpose; and when they picked me up, I was not hurt, but I had stopped growing.", "از پله‌های زیرزمین افتادم، عمداً، به قصد؛ و وقتی بلندم کردند، آسیب ندیده بودم اما رشد را متوقف کرده بودم."),
            StoryParagraph("My mother wept; my father shouted; the doctors examined me; but none of them understood what I had done.", "مادرم گریه کرد؛ پدرم فریاد زد؛ دکترها معاینه‌ام کردند؛ اما هیچ‌کدام نمی‌فهمیدند چه کرده‌ام."),
            StoryParagraph("They said it was an accident; they said it was a shock; they said I would grow eventually, when I was ready.", "گفتند تصادف بود؛ گفتند شوکه شده؛ گفتند بالاخره رشد می‌کنم، وقتی آماده باشم."),
            StoryParagraph("But I knew, and they did not, that I had made a choice; and my choice would define the rest of my life.", "اما می‌دانستم و آن‌ها نمی‌دانستند که انتخاب کرده بودم؛ و انتخابم باقی عمرم را تعریف می‌کرد."),
            StoryParagraph("I was a dwarf, a little man, a creature of three feet tall who would remain three feet tall for the rest of his life.", "من یک کوتوله بودم، مردی کوچک، موجودی به قد سه فوت که باقی عمرش سه فوت می‌ماند."),
            StoryParagraph("But what they did not know — what they could not know — was that inside that small body, my mind was growing, expanding, sharpening.", "اما آنچه نمی‌دانستند — آنچه نمی‌توانستند بدانند — این بود که درون آن بدن کوچک، ذهنم رشد می‌کرد، گسترده می‌شد، تیز می‌شد."),
            StoryParagraph("I was the eternal child, the eternal observer, the eternal judge, and I would see everything, understand everything, remember everything.", "من کودک ابدی بودم، مشاهده‌گر ابدی، قاضی ابدی و همه چیز را می‌دیدم، همه چیز را می‌فهمیدم، همه چیز را به یاد می‌آوردم."),
            StoryParagraph("And I had my drums — my tin drums, red and white, that my mother gave me, and that I would carry with me for the rest of my life.", "و طبل‌هایم را داشتم — طبل‌های حلبی‌ام، سرخ و سفید، که مادرم به من داد و تا آخر عمرم با خود حمل می‌کردم."),
            StoryParagraph("My mother bought them for my third birthday, from a toyshop on Kohlenmarkt, and I remember the moment she handed them to me.", "مادرم آن‌ها را برای تولد سه سالگی‌ام خرید، از اسباب‌بازی‌فروشی در کوهلن‌مارکت و لحظه‌ای که به دستم داد را به یاد می‌آورم."),
            StoryParagraph("It was a small drum, white lacquer with a red flame pattern, and it came with two wooden sticks, and I knew, immediately, that this was my instrument.", "طبل کوچکی بود، لاکی سفید با الگوی شعله سرخ و با دو چوب چوبی همراه بود و بلافاصله دانستم این ساز من است."),
            StoryParagraph("I drummed on my drums every day, every moment, and my drumming would tell the story of my life, the story of my city, the story of my century.", "هر روز، هر لحظه روی طبل‌هایم می‌کوبیدم و طبل زدنم داستان زندگی‌ام را می‌گفت، داستان شهرم را، داستان قرنم را."),
            StoryParagraph("The drums were my voice, my language, my way of speaking to a world that did not want to hear the truth.", "طبل‌ها صدایم بودند، زبانم، شیوه‌ام برای صحبت با جهانی که نمی‌خواست حقیقت را بشنود."),
            StoryParagraph("And in that world — the world of Danzig in the 1920s and 1930s — there was much that needed to be said, and little that could be said in words.", "و در آن جهان — جهان دانزیگ در دهه‌های ۱۹۲۰ و ۱۹۳۰ — چیزهای بسیاری بود که باید گفته می‌شد و اندکی که می‌شد در کلمات گفت."),
            StoryParagraph("The Nazis were rising; the Poles were preparing; the Germans were dreaming of empire; and my city, the Free City of Danzig, was caught in the middle, a prize to be fought over.", "نازی‌ها بالا می‌آمدند؛ لهستانی‌ها آماده می‌شدند؛ آلمانی‌ها در خواب امپراتوری بودند؛ و شهر من، شهر آزاد دانزیگ، در میان گرفتار بود، جایزه‌ای که باید بر سرش جنگید."),
            StoryParagraph("I saw it all; I heard it all; I remembered it all; and I drummed it all, on my tin drums, red and white, until the day they took them away from me.", "همه‌اش را دیدم؛ همه‌اش را شنیدم؛ همه‌اش را به یاد آوردم؛ و همه‌اش را طبل زدم، روی طبل‌های حلبی‌ام، سرخ و سفید، تا روزی که از من گرفتندشان."),
            StoryParagraph("But that is later; for now, there is only the beginning: a birth, a decision, a drum, and a world preparing itself for the greatest catastrophe in human history.", "اما آن بعدتر است؛ برای اکنون، تنها آغاز هست: تولدی، تصمیمی، طبلی و جهانی که خودش را برای بزرگ‌ترین فاجعه تاریخ بشر آماده می‌کند."),
            StoryParagraph("And a small boy, three feet tall, who would not grow, and who would see everything, and who would tell the truth.", "و پسرکی کوچک، سه فوت قد، که رشد نمی‌کرد و همه چیز را می‌دید و حقیقت را می‌گفت."),
            StoryParagraph("That small boy was me; that small boy is still me; that small boy will always be me, as long as these words are read.", "آن پسرک کوچک من بودم؛ آن پسرک کوچک هنوز من است؛ آن پسرک کوچک همیشه من خواهد بود، تا وقتی این کلمات خوانده شوند."),
            StoryParagraph("And so my story begins — not with the beginning of my life, but with the beginning of my memory, which is the only life that matters.", "و اینگونه داستان من آغاز می‌شود — نه با آغاز زندگی‌ام، بلکه با آغاز حافظه‌ام، که تنها زندگی‌ای است که اهمیت دارد.")
        )
    )

    // ─────────── فصل ۲: اگنس ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Agnes", titlePersian = "اگنس",
        paragraphs = listOf(
            StoryParagraph("My mother, Agnes, was the center of my world, the woman I loved more than anyone, the woman whose death would haunt me for the rest of my life.", "مادرم، اگنس، مرکز جهان من بود، زنی که بیش از هر کسی دوستش داشتم، زنی که مرگش تا آخر عمر تسخیرم می‌کرد."),
            StoryParagraph("She was beautiful, and she knew it, and she used her beauty like a weapon, like a shield, like a way of surviving in a world that was unkind to women.", "زیبا بود و می‌دانست و از زیبایی‌اش همچون سلاحی استفاده می‌کرد، همچون سپری، همچون شیوه‌ای برای زنده ماندن در جهانی که با زنان مهربان نبود."),
            StoryParagraph("She had dark hair, and pale skin, and eyes the color of the Baltic Sea in winter — grey-green, changeable, deep.", "موهای تیره داشت و پوستی رنگ‌پریده و چشمانی به رنگ دریای بالتیک در زمستان — خاکستری-سبز، متغیر، عمیق."),
            StoryParagraph("She had a way of looking at you that made you feel that you were the only person in the world, that she had been waiting for you, that she had always known you.", "شیوه‌ای در نگاه کردن داشت که وادارت می‌کرد حس کنی تنها شخص در جهان هستی، که او منتظرت بوده، که همیشه می‌شناخته‌ات."),
            StoryParagraph("She had married Alfred Matzerath because he was German, because he was respectable, because he offered her a kind of safety in a time of chaos.", "با آلفرد ماتسرات ازدواج کرده بود چون آلمانی بود، چون محترم بود، چون در زمانی از آشوب نوعی امنیت به او پیشنهاد می‌کرد."),
            StoryParagraph("It was 1923, and the world was in chaos; the German mark was worthless, the country was in ruins, and everyone was looking for someone to blame.", "سال ۱۹۲۳ بود و جهان در آشوب؛ مارک آلمان بی‌ارزش شده بود، کشور در ویرانه و همه به دنبال کسی بودند که سرزنش کنند."),
            StoryParagraph("Alfred had a store, a small grocery, and a future, and a certain solidity that my mother found comforting in a time when everything was falling apart.", "آلفرد مغازه‌ای داشت، بقالی کوچکی و آینده‌ای و نوعی استحکام که مادرم در زمانی که همه چیز از هم می‌پاشید آرامش‌بخش می‌یافت."),
            StoryParagraph("But she loved Jan Bronski, her cousin, her Polish lover, the man who had been her first love and who remained her only love.", "اما یان برونسکی را دوست داشت، پسرخاله‌اش، عاشق لهستانی‌اش، مردی که نخستین عشقش بوده و تنها عشقش مانده بود."),
            StoryParagraph("Jan was everything Alfred was not: gentle, sensitive, dreamy, impractical, and deeply, hopelessly in love with a woman he could not have.", "یان همه چیزی بود که آلفرد نبود: لطیف، حساس، خیال‌باف، غیرعملی و عمیقاً، ناامیدانه عاشق زنی که نمی‌توانست داشته باشد."),
            StoryParagraph("They had met as children, on the shores of the Baltic, in the small Kashubian village where their families had lived for generations.", "به‌عنوان بچه یکدیگر را ملاقات کرده بودند، در ساحل بالتیک، در دهکده کوچک کاشوبی که خانواده‌هایشان نسل‌ها در آن زندگی کرده بودند."),
            StoryParagraph("They had played together, swum together, dreamed together; and they had fallen in love, as children sometimes do, without knowing what love meant.", "با هم بازی کرده بودند، با هم شنا کرده بودند، با هم رؤیا دیده بودند؛ و عاشق شده بودند، همانطور که بچه‌ها گاهی می‌شوند، بی‌آنکه بدانند عشق یعنی چه."),
            StoryParagraph("But they were cousins, and they were Catholic, and they were poor; and so they could not marry; and so they married others; and so they were separated.", "اما پسرخاله و دخترخاله بودند و کاتولیک و فقیر؛ و بنابراین نمی‌توانستند ازدواج کنند؛ و بنابراین با دیگران ازدواج کردند؛ و بنابراین جدا شدند."),
            StoryParagraph("Every Thursday, she would take me to Jan's apartment, and there, in that small room, she would be happy, truly happy, for a few hours.", "هر پنجشنبه مرا به آپارتمان یان می‌برد و آنجا، در آن اتاق کوچک، چند ساعت خوشحال می‌شد، به‌راستی خوشحال."),
            StoryParagraph("I did not understand, at first, what was happening; I was only three, only four, only five; but I watched, and I listened, and I learned.", "اول نمی‌فهمیدم چه اتفاقی می‌افتد؛ تنها سه، چهار، پنج ساله بودم؛ اما تماشا کردم و گوش دادم و یاد گرفتم."),
            StoryParagraph("They played cards together, and they talked, and they laughed, and they loved, and I sat on the floor and watched them, and I understood everything.", "با هم ورق بازی می‌کردند و صحبت می‌کردند و می‌خندیدند و عشق می‌ورزیدند و من روی زمین می‌نشستم و تماشایشان می‌کردم و همه چیز را می‌فهمیدم."),
            StoryParagraph("I understood that my mother was unhappy in her marriage, that she was living a lie, that she was trapped between two men and two nations and two impossible futures.", "می‌فهمیدم مادرم در ازدواجش ناخوشحال بود، دروغی زندگی می‌کرد، میان دو مرد و دو ملت و دو آینده ناممکن گرفتار بود."),
            StoryParagraph("I understood that Jan loved her, truly loved her, in a way that Alfred could never love anyone.", "می‌فهمیدم یان دوستش داشت، به‌راستی دوستش داشت، به شیوه‌ای که آلفرد هرگز نمی‌توانست کسی را دوست بدارد."),
            StoryParagraph("I understood that their love was doomed, that it could not survive in a world that was preparing for war, that it would be destroyed by the very forces that were gathering around us.", "می‌فهمیدم عشقشان محکوم بود، نمی‌توانست در جهانی که خودش را برای جنگ آماده می‌کرد زنده بماند، توسط همان نیروهایی که دورمان جمع می‌شدند نابود می‌شد."),
            StoryParagraph("My mother was a Catholic, and she believed in God, and she believed in sin, and she believed that she was damned.", "مادرم کاتولیک بود و به خدا باور داشت و به گناه و باور داشت که نفرین شده."),
            StoryParagraph("She went to confession every week; she took communion every Sunday; but she could not give up Jan, and she could not forgive herself.", "هر هفته اعتراف می‌رفت؛ هر یکشنبه عشای ربانی می‌گرفت؛ اما نمی‌توانست یان را رها کند و نمی‌توانست خودش را ببخشد."),
            StoryParagraph("She confessed her sin, and the priest gave her absolution, and she went out and sinned again, and she came back and confessed again.", "گناهش را اعتراف می‌کرد و کشیش بخشش می‌داد و او بیرون می‌رفت و دوباره گناه می‌کرد و برمی‌گشت و دوباره اعتراف می‌کرد."),
            StoryParagraph("It was a cycle that could not be broken, because the sin was also her only happiness, because the guilt was also her only proof that she was alive.", "چرخه‌ای بود که نمی‌شد شکست، زیرا گناه تنها خوشبختی‌اش هم بود، زیرا گناه تنها اثبات زنده بودنش هم بود."),
            StoryParagraph("And slowly, year by year, her beauty faded, her spirit weakened, her body grew thin, and her eyes grew distant.", "و به‌آرامی، سال به سال، زیبایی‌اش محو شد، روحش ضعیف شد، بدنش لاغر شد و چشمانش دور شدند."),
            StoryParagraph("She began to spend more time at Jan's apartment, less time at home; she began to forget about the store, about the cooking, about the small duties of daily life.", "شروع کرد به گذراندن وقت بیشتری در آپارتمان یان، وقت کمتری در خانه؛ شروع کرد به فراموش کردن مغازه، آشپزی، وظایف کوچک زندگی روزمره."),
            StoryParagraph("Alfred complained, but weakly; he did not have the courage to confront her, or perhaps he did not have the courage to know the truth.", "آلفرد شکایت می‌کرد اما ضعیف؛ جرات نداشت با او روبرو شود، یا شاید جرات نداشت حقیقت را بداند."),
            StoryParagraph("And so the years passed, and my mother grew more beautiful and more sad, and my father grew more invisible, and Jan grew more desperate.", "و اینگونه سال‌ها گذشت و مادرم زیباتر و غمگین‌تر شد و پدرم نامرئی‌تر و یان ناامیدتر."),
            StoryParagraph("One day, she told me she was going to have a child; she did not say whose child it was, but I knew, and she knew that I knew.", "یک روز به من گفت بچه‌دار می‌شود؛ نگفت بچه کیست اما می‌دانستم و او می‌دانست که می‌دانم."),
            StoryParagraph("She did not want this child; she did not want to bring another life into a world that was already too crowded with suffering.", "این بچه را نمی‌خواست؛ نمی‌خواست زندگی دیگری به جهانی بیاورد که از قبل از رنج بیش از حد پر بود."),
            StoryParagraph("But she could not prevent it, and so she carried it, and she grew sadder, and she grew sicker, and she grew more beautiful in a terrible, fragile way.", "اما نمی‌توانست جلویش را بگیرد و بنابراین حملش کرد و غمگین‌تر شد و مریض‌تر شد و به شکلی هولناک و شکننده زیباتر شد."),
            StoryParagraph("She stopped eating; she stopped caring; she stopped living, though her body continued to move through the motions of life.", "از خوردن دست کشید؛ از اهمیت دادن دست کشید؛ از زندگی کردن دست کشید، هرچند بدنش به حرکات زندگی ادامه می‌داد."),
            StoryParagraph("I remember the last day I saw her, in the apartment, before she was taken to the hospital; she was sitting by the window, looking out at the grey Baltic sky.", "آخرین روزی که دیدمش را به یاد می‌آورم، در آپارتمان، قبل از بردنش به بیمارستان؛ کنار پنجره نشسته بود و به آسمان خاکستری بالتیک نگاه می‌کرد."),
            StoryParagraph("She was wearing a blue dress, and her hair was loose, and she was so beautiful, so terribly beautiful, that I could not look at her without wanting to cry.", "پیراهنی آبی پوشیده بود و موهایش باز بود و چنان زیبا بود، چنان به‌شکل هولناکی زیبا، که نمی‌توانستم بدون خواستن گریه به او نگاه کنم."),
            StoryParagraph("She turned to me, and she smiled, and she said, 'Oskar, my little Oskar, I am sorry.'", "به من برگشت و لبخند زد و گفت: «اسکار، اسکار کوچولوی من، متأسفم.»"),
            StoryParagraph("She did not say what she was sorry for; she did not have to; I knew, and she knew that I knew.", "نگفت برای چه متأسف است؛ مجبور نبود؛ می‌دانستم و او می‌دانست که می‌دانم."),
            StoryParagraph("And then, one day, she died.", "و بعد، یک روز، مرد."),
            StoryParagraph("She died from eating fish, from food poisoning, from something that the doctors could not quite explain; but I knew, and she knew, that she had died from sorrow.", "از خوردن ماهی مرد، از مسمومیت غذایی، از چیزی که دکترها کاملاً نمی‌توانستند توضیح دهند؛ اما می‌دانستم و او می‌دانست که از اندوه مرده بود."),
            StoryParagraph("She died because she could not live with the lie any longer, because she could not bear the world that was coming, because she could not protect her children from what was about to happen.", "مرد چون دیگر نمی‌توانست با دروغ زندگی کند، چون نمی‌توانست جهانی را که می‌آمد تحمل کند، چون نمی‌توانست بچه‌هایش را از آنچه در شرف وقوع بود محافظت کند."),
            StoryParagraph("I drummed at her funeral, on my tin drum, slowly, sadly, with all the grief that a small boy could hold.", "در خاکسپاری‌اش طبل زدم، روی طبل حلبی‌ام، آهسته، غمگین، با تمام اندوهی که پسرکی کوچک می‌توانست حمل کند."),
            StoryParagraph("The priest looked at me with disapproval; the mourners whispered; but I did not care; I drummed for my mother, and I would drum for her forever.", "کشیش با نارضایتی نگاهم کرد؛ عزاداران زمزمه کردند؛ اما اهمیت نمی‌دادم؛ برای مادرم طبل زدم و برای همیشه برایش طبل می‌زدم."),
            StoryParagraph("And after that, the world continued, as the world always continues, indifferent to the grief of a child who has lost his mother.", "و بعد از آن، جهان ادامه یافت، همانطور که جهان همیشه ادامه می‌یابد، بی‌تفاوت به اندوه بچه‌ای که مادرش را از دست داده."),
            StoryParagraph("But I did not continue; I could not continue; a part of me died with her, and that part would never come back.", "اما من ادامه نیافتم؛ نمی‌توانستم ادامه دهم؛ بخشی از من با او مرد و آن بخش هرگز بازنمی‌گشت."),
            StoryParagraph("I was six years old, and I had lost the only person who had ever truly loved me.", "شش ساله بودم و تنها کسی که هرگز به‌راستی دوستم داشته بود را از دست داده بودم."),
            StoryParagraph("And I would spend the rest of my life searching for her, in my drums, in my memories, in my words.", "و باقی عمرم را صرف جستجویش می‌کردم، در طبل‌هایم، در خاطراتم، در کلماتم."),
            StoryParagraph("But she was gone; she was truly gone; and nothing would ever bring her back.", "اما رفته بود؛ به‌راستی رفته بود؛ و هیچ چیز هرگز بازش نمی‌گرداند."),
            StoryParagraph("Except the drum; the drum could bring her back; the drum could bring anyone back, for a moment, for a memory, for a heartbeat.", "جز طبل؛ طبل می‌توانست بازش گرداند؛ طبل می‌توانست هر کسی را بازگرداند، برای لحظه‌ای، برای خاطره‌ای، برای یک ضربان قلب."),
            StoryParagraph("And so I drummed, and I would always drum, and in my drumming, my mother lived.", "و اینگونه طبل زدم و همیشه طبل می‌زدم و در طبل زدنم، مادرم زندگی می‌کرد.")
        )
    )

    // ─────────── فصل ۳: جنگ ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "The War", titlePersian = "جنگ",
        paragraphs = listOf(
            StoryParagraph("The war came to Danzig on the first of September, 1939, and it came with a sound that I would never forget: the sound of guns and bombs and men dying.", "جنگ در نخستین روز سپتامبر ۱۹۳۹ به دانزیگ آمد و با صدایی آمد که هرگز فراموش نمی‌کردم: صدای تفنگ‌ها و بمب‌ها و مردانی که می‌مردند."),
            StoryParagraph("I was fifteen years old, but I looked like a child of three, because I had chosen not to grow.", "پانزده ساله بودم اما مثل بچه‌ای سه ساله به نظر می‌رسیدم، چون انتخاب کرده بودم رشد نکنم."),
            StoryParagraph("And so I watched the war from a strange position, from the position of the eternal child, from the position of a boy who would never become a man.", "و بنابراین جنگ را از موقعیتی عجیب تماشا کردم، از موقعیت کودک ابدی، از موقعیت پسری که هرگز مرد نمی‌شد."),
            StoryParagraph("The German battleship Schleswig-Holstein had been anchored in the harbor of Danzig, ostensibly for a friendly visit, but on that morning it opened fire on the Polish post office.", "نبردناو آلمانی شلسویگ-هولشتاین در بندر دانزیگ لنگر انداخته بود، ظاهراً برای بازدید دوستانه، اما آن صبح آتش گشود به سمت پست لهستان."),
            StoryParagraph("I was there; I saw it; I heard the first shots of the Second World War.", "من آنجا بودم؛ دیدمش؛ نخستین گلوله‌های جنگ جهانی دوم را شنیدم."),
            StoryParagraph("I had gone to the post office that morning with Jan Bronski, my true father, because my mother had asked him to take me with him.", "آن صبح با یان برونسکی، پدر واقعی‌ام، به پستخانه رفته بودم، چون مادرم از او خواسته بود مرا با خود ببرد."),
            StoryParagraph("She had asked him because she was afraid; she had asked him because she knew what was coming; she had asked him because she wanted me to be safe.", "از او خواسته بود چون می‌ترسید؛ از او خواسته بود چون می‌دانست چه می‌آید؛ از او خواسته بود چون می‌خواست من امن باشم."),
            StoryParagraph("But we were not safe; we were in the middle of a battle; we were in the middle of history.", "اما امن نبودیم؛ در میانه نبردی بودیم؛ در میانه تاریخ بودیم."),
            StoryParagraph("The Poles resisted, bravely, hopelessly; they held out for hours, for days, before they were finally overwhelmed.", "لهستانی‌ها مقاومت کردند، شجاعانه، ناامیدانه؛ ساعت‌ها، روزها مقاومت کردند تا سرانجام مغلوب شدند."),
            StoryParagraph("Jan Bronski was among the defenders; he fought with a rifle that he barely knew how to use; he fought because he was Polish, because he was brave, because he had no choice.", "یان برونسکی میان مدافعان بود؛ با تفنگی که به‌سختی می‌دانست چگونه استفاده کند جنگید؛ جنگید چون لهستانی بود، چون شجاع بود، چون چاره‌ای نداشت."),
            StoryParagraph("And when the battle was over, when the Germans had won, when the post office had fallen, he was captured.", "و وقتی نبرد تمام شد، وقتی آلمانی‌ها برنده شدند، وقتی پستخانه سقوط کرد، اسیر شد."),
            StoryParagraph("I was captured too, but I was a child, a small child of three, and so they let me go; they did not know what to do with me.", "من هم اسیر شدم اما بچه بودم، بچه‌ای کوچک سه ساله و بنابراین رهایم کردند؛ نمی‌دانستند با من چه کنند."),
            StoryParagraph("I watched as they led Jan away, with the other Polish prisoners, to the field where they would be executed.", "تماشا کردم که یان را بردند، با دیگر اسرای لهستانی، به مزرعه‌ای که در آن اعدام می‌شدند."),
            StoryParagraph("I wanted to call out to him; I wanted to tell him that I loved him; I wanted to tell him that he was my father.", "می‌خواستم صدایش کنم؛ می‌خواستم بگویم دوستش دارم؛ می‌خواستم بگویم پدرم است."),
            StoryParagraph("But I did not; I could not; I was frozen, silent, unable to move or speak.", "اما نکردم؛ نمی‌توانستم؛ منجمد بودم، ساکت، ناتوان از حرکت یا سخن."),
            StoryParagraph("He looked at me, just once, as they led him past; he looked at me with love and sorrow and something like peace.", "یک بار، همانطور که از کنارم می‌بردندش، نگاهم کرد؛ با عشق و اندوه و چیزی شبیه آرامش نگاهم کرد."),
            StoryParagraph("And then he was gone, and I never saw him again.", "و بعد رفت و هرگز دوباره ندیدمش."),
            StoryParagraph("I learned of his death from a German soldier, a man who did not even know what he was telling me; and I did not weep, because I could not weep, because I could not feel.", "از سربازی آلمانی از مرگش مطلع شدم، مردی که حتی نمی‌دانست به من چه می‌گوید؛ و گریه نکردم، چون نمی‌توانستم گریه کنم، چون نمی‌توانستم حس کنم."),
            StoryParagraph("Not then; the tears would come later, years later, when the war was over and the world had changed and I had time to think about what I had lost.", "نه آن موقع؛ اشک‌ها بعدتر می‌آمدند، سال‌ها بعد، وقتی جنگ تمام شده بود و جهان تغییر کرده بود و وقت داشتم فکر کنم چه از دست داده‌ام."),
            StoryParagraph("But at that moment, in those days, there was only the war, and the war was everywhere.", "اما در آن لحظه، در آن روزها، تنها جنگ بود و جنگ همه‌جا بود."),
            StoryParagraph("Alfred Matzerath, my stepfather, joined the Nazi Party and became a minor official; he was proud of his uniform, proud of his membership, proud of his small power.", "آلفرد ماتسرات، ناپدری‌ام، به حزب نازی پیوست و مقامی کوچک شد؛ به یونیفرمش افتخار می‌کرد، به عضویتش، به قدرت کوچکش."),
            StoryParagraph("He believed in Hitler; he believed in the German Reich; he believed in the future that the Nazis promised.", "به هیتلر باور داشت؛ به رایش آلمان باور داشت؛ به آینده‌ای که نازی‌ها وعده می‌دادند باور داشت."),
            StoryParagraph("And when the Nazis began to round up the Jews, and the Poles, and the gypsies, and the mentally ill, he did not protest.", "و وقتی نازی‌ها شروع کردند به گرد آوردن یهودیان و لهستانی‌ها و کولی‌ها و بیماران روانی، اعتراض نکرد."),
            StoryParagraph("When his own neighbors were taken away, when children were taken away, when the old and the sick were taken away, he did not protest.", "وقتی همسایه‌های خودش برده شدند، وقتی بچه‌ها برده شدند، وقتی پیران و بیماران برده شدند، اعتراض نکرد."),
            StoryParagraph("He simply closed his eyes, and he continued selling groceries, and he continued believing in the Reich.", "تنها چشمانش را بست و به فروش خواروبار ادامه داد و به باور به رایش ادامه داد."),
            StoryParagraph("And I drummed; I drummed on my tin drum; I drummed for the dead, for the lost, for the forgotten.", "و من طبل زدم؛ روی طبل حلبی‌ام زدم؛ برای مردگان زدم، برای گمشدگان، برای فراموششدگان."),
            StoryParagraph("I drummed in the streets, in the market squares, in the ruins; and sometimes, when I drummed, people stopped and listened, and sometimes they wept.", "در خیابان‌ها طبل زدم، در میدان‌های بازار، در ویرانه‌ها؛ و گاهی، وقتی طبل می‌زدم، مردم می‌ایستادند و گوش می‌دادند و گاهی گریه می‌کردند."),
            StoryParagraph("The drum was my protest; the drum was my truth; the drum was my way of saying what could not be said.", "طبل اعتراضم بود؛ طبل حقیقتم بود؛ طبل شیوه‌ام برای گفتن آنچه نمی‌شد گفت."),
            StoryParagraph("Once, I drummed at a Nazi rally, and the drumming was so powerful, so strange, that the whole rally turned into a waltz.", "یک بار، در یک گردهمایی نازی طبل زدم و طبل زدن چنان قدرتمند بود، چنان عجیب، که تمام گردهمایی به والس تبدیل شد."),
            StoryParagraph("The Nazis, the goose-stepping Nazis, began to dance; they could not help themselves; the rhythm took hold of them and would not let go.", "نازی‌ها، نازی‌های قدم‌غازی، شروع کردند به رقصیدن؛ نمی‌توانستند جلوی خودشان را بگیرند؛ ریتم آن‌ها را گرفت و رهایشان نمی‌کرد."),
            StoryParagraph("It was my small revenge, my small protest, my small act of resistance in a world that was drowning in hatred.", "انتقام کوچک من بود، اعتراض کوچک من، عمل کوچک مقاومت من در جهانی که در نفرت غرق می‌شد."),
            StoryParagraph("The war went on, year after year, and the world was destroyed, and the people were destroyed, and everything that my mother had loved was destroyed.", "جنگ سال پس از سال ادامه یافت و جهان نابود شد و مردم نابود شدند و هر چیزی که مادرم دوست داشت نابود شد."),
            StoryParagraph("The Russians came from the east, and the Americans from the west, and the Germans were caught in the middle, and the cities burned, and the people died.", "روس‌ها از شرق آمدند و آمریکایی‌ها از غرب و آلمانی‌ها در میان گرفتار شدند و شهرها سوختند و مردم مردند."),
            StoryParagraph("I watched it all, from my strange position, from my eternal childhood, from the height of three feet that gave me a view that no one else had.", "همه‌اش را تماشا کردم، از موقعیت عجیبم، از کودکی ابدی‌ام، از قد سه فوتی که به من دیدی می‌داد که هیچ‌کس دیگری نداشت."),
            StoryParagraph("I saw the Nazis march, and I saw the Russians come, and I saw the city burn.", "راهپیمایی نازی‌ها را دیدم و آمدن روس‌ها را و سوختن شهر را."),
            StoryParagraph("I saw the dead in the streets, and the refugees in the roads, and the starving children in the ruins.", "مردگان را در خیابان‌ها دیدم و پناهندگان را در جاده‌ها و بچه‌های گرسنه را در ویرانه‌ها."),
            StoryParagraph("I saw things that no child should see, and I remembered them, because I could not forget them, because my memory was perfect and merciless.", "چیزهایی دیدم که هیچ بچه‌ای نباید ببیند و به یاد آوردمشان، چون نمی‌توانستم فراموششان کنم، چون حافظه‌ام کامل و بی‌رحم بود."),
            StoryParagraph("And through it all, I drummed, and through it all, I remembered, and through it all, I waited for something that I could not name.", "و در تمام این مدت طبل زدم و در تمام این مدت به یاد آوردم و در تمام این مدت منتظر چیزی ماندم که نمی‌توانستم نامش را ببرم."),
            StoryParagraph("I was waiting for the end of the war, and the beginning of the truth, and the chance to tell my story.", "منتظر پایان جنگ بودم و آغاز حقیقت و فرصت گفتن داستانم."),
            StoryParagraph("And the end of the war came, at last, in the spring of 1945, when the Russians entered Danzig and the German Reich collapsed.", "و پایان جنگ سرانجام در بهار ۱۹۴۵ آمد، وقتی روس‌ها وارد دانزیگ شدند و رایش آلمان فرو ریخت."),
            StoryParagraph("And with the end of the war came the beginning of my real life, the life of a dwarf, an orphan, a survivor, a man without a country.", "و با پایان جنگ آغاز زندگی واقعی من آمد، زندگی کوتوله‌ای، یتیمی، بازمانده‌ای، مردی بدون کشور."),
            StoryParagraph("And the drum continued; the drum always continues; the drum is the only thing that never ends.", "و طبل ادامه یافت؛ طبل همیشه ادامه می‌یابد؛ طبل تنها چیزی است که هرگز تمام نمی‌شود.")
        )
    )

    // ─────────── فصل ۴: پس از جنگ ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "After the War", titlePersian = "پس از جنگ",
        paragraphs = listOf(
            StoryParagraph("The war ended, and Danzig became Gdansk, and the Germans were expelled, and the Poles came from the east to take their place.", "جنگ تمام شد و دانزیگ گدانسک شد و آلمانی‌ها اخراج شدند و لهستانی‌ها از شرق آمدند تا جایشان را بگیرند."),
            StoryParagraph("It was a great migration, a great uprooting, a great erasure; millions of people were moved, millions of lives were changed, millions of memories were destroyed.", "مهاجرتی بزرگ بود، ریشه‌کنی‌ای بزرگ، پاک‌کردنی بزرگ؛ میلیون‌ها نفر جابه‌جا شدند، میلیون‌ها زندگی تغییر کرد، میلیون‌ها خاطره نابود شد."),
            StoryParagraph("Alfred Matzerath, my stepfather, was arrested by the Russians; he had swallowed his Nazi Party pin, and it had lodged in his throat, and it had killed him.", "آلفرد ماتسرات، ناپدری‌ام، توسط روس‌ها دستگیر شد؛ سنجاق حزب نازی‌اش را بلعیده بود و در گلویش گیر کرده بود و کشته بودش."),
            StoryParagraph("It was a fitting end, I thought, for a man who had spent his life swallowing his conscience.", "فکر کردم پایانی شایسته بود برای مردی که عمرش را صرف بلعیدن وجدانش کرده بود."),
            StoryParagraph("They buried him in a mass grave, with other Nazis, other collaborators, other men who had believed in things they should not have believed in.", "او را در گور جمعی دفن کردند، با دیگر نازی‌ها، دیگر همکاران، دیگر مردانی که به چیزهایی باور داشتند که نباید باور می‌داشتند."),
            StoryParagraph("I did not weep for him; I could not weep for him; he had never loved me, and I had never loved him, and his death meant nothing to me.", "برای او گریه نکردم؛ نمی‌توانستم گریه کنم؛ هرگز دوستم نداشته بود و من هم هرگز دوستش نداشته بودم و مرگش برایم هیچ معنایی نداشت."),
            StoryParagraph("My brother, Kurt, who had been born during the war, was now a child of four; he did not understand what had happened; he did not understand anything.", "برادرم، کورت، که در طول جنگ زاده شده بود، حالا بچه‌ای چهار ساله بود؛ نمی‌فهمید چه اتفاقی افتاده؛ هیچ چیز نمی‌فهمید."),
            StoryParagraph("I became his guardian, his protector, his parent; I was twenty-one, and he was four, and I was a dwarf, and he was a child.", "سرپرستش شدم، محافظش، پدر و مادرش؛ بیست و یک ساله بودم و او چهار، و من کوتوله بودم و او بچه."),
            StoryParagraph("We were orphans together, in a ruined city, in a ruined country, in a ruined century.", "با هم یتیم بودیم، در شهری ویران، در کشوری ویران، در قرنی ویران."),
            StoryParagraph("I decided that I would grow again; I decided that I would abandon my eternal childhood; I decided that I would enter the world of adults, though I did not understand them and did not trust them.", "تصمیم گرفتم دوباره رشد کنم؛ تصمیم گرفتم کودکی ابدی‌ام را رها کنم؛ تصمیم گرفتم به جهان بزرگسالان وارد شوم، هرچند آن‌ها را نمی‌فهمیدم و به آن‌ها اعتماد نداشتم."),
            StoryParagraph("But when I tried to grow, I could not; my body refused; my childhood was permanent; I was stuck, forever, in the body of a child.", "اما وقتی تلاش کردم رشد کنم، نتوانستم؛ بدنم امتناع کرد؛ کودکی‌ام دائمی بود؛ برای همیشه در بدن یک بچه گیر افتاده بودم."),
            StoryParagraph("I went to doctors, and they examined me, and they shook their heads; they said there was nothing they could do; they said I would be a dwarf forever.", "به دکترها رفتم و معاینه‌ام کردند و سر تکان دادند؛ گفتند کاری نمی‌توانند بکنند؛ گفتند برای همیشه کوتوله می‌مانم."),
            StoryParagraph("And so I became a different kind of person: a dwarf who had chosen his size, and who now could not escape it; a man who had refused to grow, and who now could not grow.", "و اینگونه شخص متفاوتی شدم: کوتوله‌ای که اندازه‌اش را انتخاب کرده بود و حالا نمی‌توانست از آن بگریزد؛ مردی که از رشد امتناع کرده بود و حالا نمی‌توانست رشد کند."),
            StoryParagraph("It was the first lesson of my life: that choices have consequences; that the past cannot be undone; that what we do in one moment shapes all the moments that follow.", "این نخستین درس زندگی‌ام بود: انتخاب‌ها پیامد دارند؛ گذشته را نمی‌شود بازگرداند؛ آنچه در یک لحظه می‌کنیم، تمام لحظه‌های بعدی را شکل می‌دهد."),
            StoryParagraph("I began to work as a musician, playing in nightclubs and cabarets, where my size was an attraction, a curiosity, a way of making money.", "شروع کردم به کار موسیقی، در کلوپ‌های شبانه و کاباره‌ها می‌نواختم، جایی که اندازه‌ام جاذبه‌ای بود، کنجکاوی، شیوه‌ای برای پول درآوردن."),
            StoryParagraph("I played in a jazz band, and I sang songs, and I drummed on my tin drum, and I became famous, in a small way, in the world of the German economic miracle.", "در یک گروه جاز نواختم و آواز خواندم و روی طبل حلبی‌ام زدم و مشهور شدم، به شکلی کوچک، در جهان معجزه اقتصادی آلمان."),
            StoryParagraph("The postwar years were years of forgetting; everyone wanted to forget the war, to forget the crimes, to forget the dead.", "سال‌های پس از جنگ، سال‌های فراموشی بودند؛ همه می‌خواستند جنگ را فراموش کنند، جنایات را، مردگان را."),
            StoryParagraph("They built new buildings, and drove new cars, and bought new appliances, and pretended that nothing had happened.", "ساختمان‌های جدید ساختند و ماشین‌های جدید راندند و لوازم جدید خریدند و تظاهر کردند هیچ اتفاقی نیفتاده."),
            StoryParagraph("They said that the war was a tragedy, but that it was the past, and that the past was the past, and that we must look to the future.", "گفتند جنگ تراژدی بود اما گذشته است و گذشته، گذشته است و باید به آینده نگاه کنیم."),
            StoryParagraph("They said that they had not known, that they had not participated, that they had been victims too.", "گفتند نمی‌دانستند، شرکت نکرده بودند، آن‌ها هم قربانی بودند."),
            StoryParagraph("They lied; they all lied; they had known, and they had participated, and they had not been victims, but perpetrators and bystanders.", "دروغ گفتند؛ همه‌شان دروغ گفتند؛ می‌دانستند و شرکت کرده بودند و قربانی نبودند، بلکه مرتکب و تماشاگر بودند."),
            StoryParagraph("And I too wanted to forget, or rather I wanted to pretend to forget, because to remember, in that world, was to be alone.", "و من هم می‌خواستم فراموش کنم، یا بهتر، می‌خواستم تظاهر به فراموشی کنم، چون به یاد آوردن در آن جهان، تنهایی بود."),
            StoryParagraph("But I could not forget; I could not stop remembering; my memory was perfect and merciless, and it would not let me rest.", "اما نمی‌توانستم فراموش کنم؛ نمی‌توانستم از یاد آوردن دست بکشم؛ حافظه‌ام کامل و بی‌رحم بود و رهایم نمی‌کرد."),
            StoryParagraph("I remembered my mother, and her beauty, and her sorrow, and her death.", "مادرم را به یاد می‌آوردم و زیبایی‌اش و اندوهش و مرگش را."),
            StoryParagraph("I remembered Jan Bronski, and his kindness, and his courage, and his execution.", "یان برونسکی را به یاد می‌آوردم و مهربانی‌اش و شجاعتش و اعدامش."),
            StoryParagraph("I remembered the Nazis, and their parades, and their cruelty, and their lies.", "نازی‌ها را به یاد می‌آوردم و راهپیمایی‌هایشان و بی‌رحمی‌شان و دروغ‌هایشان."),
            StoryParagraph("I remembered the war, and the bombs, and the fires, and the screams.", "جنگ را به یاد می‌آوردم و بمب‌ها و آتش‌ها و فریادها."),
            StoryParagraph("I remembered the Russians, and their tanks, and their vodka, and their brutality.", "روس‌ها را به یاد می‌آوردم و تانک‌هایشان و ودکایشان و وحشی‌گری‌شان."),
            StoryParagraph("I remembered the refugees, and their hunger, and their fear, and their hope.", "پناهندگان را به یاد می‌آوردم و گرسنگی‌شان و ترسشان و امیدشان."),
            StoryParagraph("I remembered everything, and I drummed everything, and I told my story to anyone who would listen.", "همه چیز را به یاد می‌آوردم و همه‌اش را طبل می‌زدم و داستانم را به هر کسی که گوش می‌داد می‌گفتم."),
            StoryParagraph("Some listened; most did not; most did not want to hear the truth, because the truth was too painful, because the truth was too heavy.", "بعضی گوش دادند؛ بیشترشان نه؛ بیشترشان نمی‌خواستند حقیقت را بشنوند، چون حقیقت بیش از حد دردناک بود، چون حقیقت بیش از حد سنگین بود."),
            StoryParagraph("And slowly, over the years, I began to understand something about the world, about humanity, about myself.", "و به‌آرامی، در طول سال‌ها، شروع کردم به فهمیدن چیزی درباره جهان، درباره بشریت، درباره خودم."),
            StoryParagraph("I understood that the world does not learn from its mistakes; that humanity repeats its crimes; that history is a circle, not a line.", "فهمیدم جهان از اشتباهاتش درس نمی‌گیرد؛ بشریت جنایاتش را تکرار می‌کند؛ تاریخ دایره است، نه خط."),
            StoryParagraph("I understood that memory is the only form of justice; that to remember is to resist; that to forget is to be complicit.", "فهمیدم حافظه تنها شکل عدالت است؛ به یاد آوردن مقاومت است؛ فراموش کردن همدستی."),
            StoryParagraph("I understood that silence is not neutral; that silence is a choice; that silence is a form of betrayal.", "فهمیدم سکوت بی‌طرف نیست؛ سکوت انتخابی است؛ سکوت نوعی خیانت است."),
            StoryParagraph("And I understood that I, Oskar Matzerath, the eternal child, the drummer, the dwarf, was a kind of witness, a kind of prophet, a kind of fool.", "و فهمیدم من، اسکار ماتسرات، کودک ابدی، طبل‌زن، کوتوله، نوعی شاهد بودم، نوعی پیامبر، نوعی احمق."),
            StoryParagraph("I was the fool who told the truth; I was the child who saw what adults refused to see; I was the drummer who beat the rhythm of a dying world.", "احمقی بودم که حقیقت را می‌گفت؛ بچه‌ای بودم که می‌دید آنچه بزرگسالان از دیدنش امتناع می‌کردند؛ طبل‌زنی بودم که ریتم جهانی در حال مرگ را می‌کوبید."),
            StoryParagraph("And so I continued, in the new Germany, in the new Europe, in the new world; I continued to drum, and to remember, and to tell the truth.", "و اینگونه ادامه دادم، در آلمان جدید، در اروپای جدید، در جهان جدید؛ به طبل زدن ادامه دادم و به یاد آوردن و گفتن حقیقت."),
            StoryParagraph("For the drum does not end; the drum never ends; the drum is the only thing that is truly eternal.", "زیرا طبل تمام نمی‌شود؛ طبل هرگز تمام نمی‌شود؛ طبل تنها چیزی است که به‌راستی ابدی است.")
        )
    )

    // ─────────── فصل ۵: طبل ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Drum", titlePersian = "طبل",
        paragraphs = listOf(
            StoryParagraph("My tin drum was my most precious possession, the one thing in the world that I truly loved, the one thing that made me who I was.", "طبل حلبی‌ام گرانبهاترین دارایی‌ام بود، تنها چیزی در جهان که به‌راستی دوستش داشتم، تنها چیزی که مرا آنچه بودم می‌کرد."),
            StoryParagraph("It was red and white, with a picture of a heart and a lamb on the side, and it had been given to me by my mother when I was three years old.", "سرخ و سفید بود، با تصویری از یک قلب و یک بره در کنارش و مادرم وقتی سه ساله بودم آن را به من داده بود."),
            StoryParagraph("I carried it with me everywhere; I slept with it; I ate with it; I took it to school, to church, to funerals.", "همه‌جا با خودم حملش می‌کردم؛ با آن می‌خوابیدم؛ با آن غذا می‌خوردم؛ به مدرسه بردمش، به کلیسا، به خاکسپاری‌ها."),
            StoryParagraph("When I was separated from it, I became sick; when I was reunited with it, I became well; the drum was my medicine, my sanity, my life.", "وقتی از آن جدا می‌شدم، مریض می‌شدم؛ وقتی به آن بازمی‌گشتم، خوب می‌شدم؛ طبل داروی من بود، سلامت عقلم، زندگی‌ام."),
            StoryParagraph("And every day, I drummed on it, with my sticks, with my fingers, with my whole body.", "و هر روز رویش طبل می‌زدم، با چوب‌هایم، با انگشتانم، با تمام بدنم."),
            StoryParagraph("My drumming was not music, in the usual sense; it was something older, something deeper, something more primitive.", "طبل زدنم موسیقی نبود، به معنای معمول؛ چیزی کهن‌تر بود، عمیق‌تر، بدوی‌تر."),
            StoryParagraph("It was the heartbeat of the world; it was the rhythm of history; it was the pulse of life itself.", "ضربان قلب جهان بود؛ ریتم تاریخ بود؛ نبض خود زندگی بود."),
            StoryParagraph("When I drummed, I could make people remember things they had forgotten; I could make them see things they had refused to see; I could make them feel things they had buried.", "وقتی طبل می‌زدم می‌توانستم مردم را وادار کنم چیزهایی که فراموش کرده بودند را به یاد بیاورند؛ می‌توانستم وادارشان کنم چیزهایی که از دیدنشان امتناع کرده بودند را ببینند؛ می‌توانستم وادارشان کنم چیزهایی که دفن کرده بودند را حس کنند."),
            StoryParagraph("Once, I drummed at a Nazi rally, and the drumming was so powerful, so strange, that the whole rally turned into a waltz.", "یک بار، در یک گردهمایی نازی طبل زدم و طبل زدن چنان قدرتمند بود، چنان عجیب، که تمام گردهمایی به والس تبدیل شد."),
            StoryParagraph("The Nazis, the goose-stepping Nazis, began to dance; they could not help themselves; the rhythm took hold of them and would not let go.", "نازی‌ها، نازی‌های قدم‌غازی، شروع کردند به رقصیدن؛ نمی‌توانستند جلوی خودشان را بگیرند؛ ریتم آن‌ها را گرفت و رهایشان نمی‌کرد."),
            StoryParagraph("It was my small revenge, my small protest, my small act of resistance in a world that was drowning in hatred.", "انتقام کوچک من بود، اعتراض کوچک من، عمل کوچک مقاومت من در جهانی که در نفرت غرق می‌شد."),
            StoryParagraph("The drum was also my way of mourning; when I drummed for the dead, I brought them back, for a moment, into the world of the living.", "طبل همچنین شیوه عزاداری‌ام بود؛ وقتی برای مردگان طبل می‌زدم، آن‌ها را برای لحظه‌ای به جهان زندگان بازمی‌گرداندم."),
            StoryParagraph("I drummed for my mother, and for Jan Bronski, and for all the victims of the war, and for all the victims of history.", "برای مادرم طبل زدم و برای یان برونسکی و برای همه قربانیان جنگ و برای همه قربانیان تاریخ."),
            StoryParagraph("And the drum answered me; the drum always answered; the drum was the only thing that never lied.", "و طبل پاسخم داد؛ طبل همیشه پاسخ می‌داد؛ طبل تنها چیزی بود که هرگز دروغ نمی‌گفت."),
            StoryParagraph("When I drummed, I was not a dwarf, not a cripple, not a freak; I was a musician, a poet, a prophet; I was the voice of the voiceless.", "وقتی طبل می‌زدم، کوتوله نبودم، نه معلول، نه عجیب‌الخلقه؛ نوازنده بودم، شاعر، پیامبر؛ صدای بی‌صدایان بودم."),
            StoryParagraph("When I drummed, I was not alone; I was connected to something larger than myself; I was part of the great rhythm of existence.", "وقتی طبل می‌زدم، تنها نبودم؛ به چیزی بزرگ‌تر از خودم وصل بودم؛ بخشی از ریتم بزرگ هستی بودم."),
            StoryParagraph("The drum was my language, my memory, my identity, my soul; to explain it would be to destroy it.", "طبل زبانم بود، حافظه‌ام، هویتم، روحم؛ توضیحش نابودش می‌کرد."),
            StoryParagraph("People asked me, sometimes, why I drummed; they asked me what my drumming meant; they asked me to explain.", "مردم گاهی از من می‌پرسیدند چرا طبل می‌زنم؛ می‌پرسیدند طبل زدنم چه معنایی دارد؛ می‌خواستند توضیح دهم."),
            StoryParagraph("But I could not explain; the drum was beyond explanation; the drum was the drum, and that was all.", "اما نمی‌توانستم توضیح دهم؛ طبل فراتر از توضیح بود؛ طبل طبل بود و همین."),
            StoryParagraph("The drum was my connection to my mother; when I drummed, I felt her presence, her love, her sorrow.", "طبل ارتباطم با مادرم بود؛ وقتی طبل می‌زدم، حضورش را حس می‌کردم، عشقش، اندوهش."),
            StoryParagraph("The drum was my connection to Jan Bronski; when I drummed, I felt his gentleness, his courage, his sacrifice.", "طبل ارتباطم با یان برونسکی بود؛ وقتی طبل می‌زدم، لطافتش را حس می‌کردم، شجاعتش، فداکاری‌اش."),
            StoryParagraph("The drum was my connection to all those who had died, all those who had suffered, all those who had been forgotten.", "طبل ارتباطم با همه کسانی بود که مرده بودند، همه کسانی که رنج کشیده بودند، همه کسانی که فراموش شده بودند."),
            StoryParagraph("And so I continued to drum, in silence, in loneliness, in the small world of my small body.", "و اینگونه به طبل زدن ادامه دادم، در سکوت، در تنهایی، در جهان کوچک بدن کوچکم."),
            StoryParagraph("I drummed in the asylum where I was eventually confined, and I drummed in my dreams, and I drummed in my memory.", "در تیمارستانی که سرانجام در آن محبوس شدم طبل زدم و در خواب‌هایم طبل زدم و در حافظه‌ام طبل زدم."),
            StoryParagraph("I was sent to the asylum after the trial, after the incident, after everything that happened; but even there, even in the madhouse, I drummed.", "پس از محاکمه به تیمارستان فرستاده شدم، پس از حادثه، پس از هر چیزی که اتفاق افتاد؛ اما حتی آنجا، حتی در دیوانه‌خانه، طبل زدم."),
            StoryParagraph("And when I wrote this book, this confession, this chronicle, I was still drumming, in a way, because the words on the page were the drums in my head.", "و وقتی این کتاب را نوشتم، این اعتراف، این تاریخ‌نگاری، به نوعی هنوز طبل می‌زدم، چون کلمات روی صفحه طبل‌های درون سرم بودند."),
            StoryParagraph("The tin drum had told my story, and would continue to tell it, as long as anyone was willing to listen.", "طبل حلبی داستانم را گفته بود و به گفتنش ادامه می‌داد، تا وقتی کسی مایل به شنیدن باشد."),
            StoryParagraph("But there is another drum, a drum that is not made of tin, a drum that beats in the heart of every human being.", "اما طبل دیگری هم هست، طبلی که از حلبی نیست، طبلی که در قلب هر انسانی می‌کوبد."),
            StoryParagraph("That drum is the drum of memory, the drum of truth, the drum of conscience; and it beats whether we want it to or not.", "آن طبل، طبل حافظه است، طبل حقیقت، طبل وجدان؛ و می‌کوبد خواه بخواهیم خواه نخواهیم."),
            StoryParagraph("We can try to silence it; we can try to cover it; we can try to pretend that we do not hear it.", "می‌توانیم تلاش کنیم ساکتش کنیم؛ می‌توانیم تلاش کنیم بپوشانیمش؛ می‌توانیم تلاش کنیم تظاهر کنیم نمی‌شنویمش."),
            StoryParagraph("But it will not be silenced; it will not be covered; it will not be denied; it will beat, and beat, and beat, until we listen.", "اما ساکت نمی‌شود؛ پوشانده نمی‌شود؛ انکار نمی‌شود؛ می‌کوبد و می‌کوبد و می‌کوبد، تا وقتی گوش دهیم."),
            StoryParagraph("That is the deepest meaning of the tin drum: that memory cannot be killed; that truth cannot be buried; that history cannot be forgotten.", "این عمیق‌ترین معنای طبل حلبی است: حافظه را نمی‌توان کشت؛ حقیقت را نمی‌توان دفن کرد؛ تاریخ را نمی‌توان فراموش کرد."),
            StoryParagraph("And so, whenever I drum, I am not just telling my own story; I am telling the story of everyone who has ever suffered, everyone who has ever died, everyone who has ever been forgotten.", "و بنابراین، هر وقت طبل می‌زنم، نه تنها داستان خودم را تعریف می‌کنم؛ داستان هر کسی را که هرگز رنج کشیده، هر کسی که هرگز مرده، هر کسی که هرگز فراموش شده را تعریف می‌کنم."),
            StoryParagraph("I drum for the dead; I drum for the living; I drum for the world; and I will drum until the end of my days.", "برای مردگان طبل می‌زنم؛ برای زندگان؛ برای جهان؛ و تا پایان روزهایم طبل می‌زنم."),
            StoryParagraph("This is the drum; this is the tin drum; this is the heartbeat of a century.", "این طبل است؛ این طبل حلبی است؛ این ضربان قلب یک قرن است."),
            StoryParagraph("And it will not be silenced.", "و ساکت نمی‌شود.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("The Tin Drum, published in 1959, is one of the greatest novels of the twentieth century, and one of the most controversial.", "طبل حلبی، منتشرشده در ۱۹۵۹، یکی از بزرگ‌ترین رمان‌های قرن بیستم و یکی از بحث‌برانگیزترین است."),
            StoryParagraph("It tells the story of Oskar Matzerath, a dwarf who chose not to grow at the age of three, and who lived through the rise of Nazism, the Second World War, and the German economic miracle.", "داستان اسکار ماتسرات را تعریف می‌کند، کوتوله‌ای که در سه سالگی انتخاب کرد رشد نکند و ظهور نازیسم را زیست، جنگ جهانی دوم را و معجزه اقتصادی آلمان را."),
            StoryParagraph("But it is not just a historical novel; it is a philosophical novel, a satirical novel, a picaresque novel, a novel of ideas.", "اما تنها رمان تاریخی نیست؛ رمانی فلسفی است، رمانی هجایی، رمانی پیکارسک، رمانی از ایده‌ها."),
            StoryParagraph("It is, above all, a novel about memory — about the need to remember, and the temptation to forget, and the impossibility of ever fully escaping the past.", "بیش از همه، رمانی است درباره حافظه — درباره نیاز به یاد آوردن و وسوسه فراموش کردن و ناممکن بودن هرگز کاملاً گریختن از گذشته."),
            StoryParagraph("Oskar is the perfect narrator for such a novel, because he is both inside and outside the world he describes.", "اسکار راوی کاملی برای چنین رمانی است، زیرا هم درون و هم بیرون جهانی است که توصیفش می‌کند."),
            StoryParagraph("He is inside because he lived through it all; he is outside because his small size, his eternal childhood, gives him a perspective that no adult could have.", "درون است چون همه‌اش را زیسته؛ بیرون است چون اندازه کوچکش، کودکی ابدی‌اش، به او دیدی می‌دهد که هیچ بزرگسالی نمی‌تواند داشته باشد."),
            StoryParagraph("He is the eternal child, the eternal observer, the eternal judge; and his voice is the voice of a century that has seen too much and understood too little.", "او کودک ابدی است، مشاهده‌گر ابدی، قاضی ابدی؛ و صدایش صدای قرنی است که بیش از حد دیده و کم فهمیده."),
            StoryParagraph("The novel's central theme is the relationship between the individual and history — between the small person and the vast forces that shape his life.", "مضمون محوری رمان رابطه میان فرد و تاریخ است — میان شخص کوچک و نیروهای عظیمی که زندگی‌اش را شکل می‌دهند."),
            StoryParagraph("Oskar chooses not to grow, but he cannot choose not to live; he is caught in the current of history, like everyone else, and he must find a way to survive.", "اسکار انتخاب می‌کند رشد نکند اما نمی‌تواند انتخاب کند زندگی نکند؛ در جریان تاریخ گرفتار است، همچون هر کس دیگری و باید راهی برای زنده ماندن بیابد."),
            StoryParagraph("And the way he finds is his drum — his tin drum, red and white, which he beats to remind the world of what it has tried to forget.", "و راهی که می‌یابد طبلش است — طبل حلبی‌اش، سرخ و سفید، که می‌کوبد تا جهان را به یاد آنچه تلاش کرده فراموش کند بیاورد."),
            StoryParagraph("The drum is his memory, his conscience, his protest, his art; and it is also, in a deeper sense, the novel itself.", "طبل حافظه‌اش است، وجدانش، اعتراضش، هنرش؛ و همچنین، به معنای عمیق‌تر، خود رمان است."),
            StoryParagraph("For The Tin Drum is a drum: it beats out the rhythm of a terrible century, and it forces us to listen, whether we want to or not.", "زیرا طبل حلبی خودش طبل است: ریتم قرنی هولناک را می‌کوبد و ما را وادار به گوش دادن می‌کند، خواه بخواهیم خواه نخواهیم."),
            StoryParagraph("The novel is also about guilt — the guilt of the Germans for the crimes of the Nazi era, and the guilt of the world for allowing those crimes to happen.", "رمان همچنین درباره گناه است — گناه آلمانی‌ها برای جنایات دوران نازی و گناه جهان برای اجازه دادن به وقوع آن جنایات."),
            StoryParagraph("Oskar is not a Nazi; he is not a hero; he is not a victim; he is a survivor, which means he is complicit in a way that no one can escape.", "اسکار نازی نیست؛ قهرمان نیست؛ قربانی نیست؛ بازمانده است، که یعنی به شیوه‌ای همدست است که هیچ‌کس نمی‌تواند از آن بگریزد."),
            StoryParagraph("He survives because he drums; he survives because he remembers; he survives because he refuses to become what the world wants him to be.", "زنده می‌ماند چون طبل می‌زند؛ زنده می‌ماند چون به یاد می‌آورد؛ زنده می‌ماند چون از تبدیل شدن به آنچه جهان می‌خواهد امتناع می‌کند."),
            StoryParagraph("And that, Grass suggests, is the only heroism available to us: not to resist heroically, but to remember honestly, to witness truthfully, to drum persistently.", "و این، گراس پیشنهاد می‌دهد، تنها قهرمانی‌ای است که برایمان در دسترس است: نه مقاومت قهرمانانه، بلکه به یاد آوردن صادقانه، شهادت دادن راستین، طبل زدن پیوسته."),
            StoryParagraph("The Tin Drum is not an easy novel; it is long, and complex, and often disturbing.", "طبل حلبی رمان آسانی نیست؛ طولانی است و پیچیده و اغلب آشفته‌کننده."),
            StoryParagraph("It contains scenes of violence, of sexuality, of madness, of cruelty; it contains passages that are difficult to read, that are designed to disturb, to provoke, to unsettle.", "صحنه‌هایی از خشونت دارد، از جنسیت، از جنون، از بی‌رحمی؛ قطعاتی دارد که خواندنشان دشوار است، که طراحی شده‌اند که آشفته کنند، برانگیزند، بی‌قرار کنند."),
            StoryParagraph("But it is a great novel, a necessary novel, a novel that must be read if we are to understand the twentieth century.", "اما رمانی بزرگ است، ضروری، رمانی که باید خوانده شود اگر می‌خواهیم قرن بیستم را بفهمیم."),
            StoryParagraph("It is a novel about a dwarf, and about a drum, and about a city; but it is also a novel about all of us.", "رمانی است درباره کوتوله‌ای و درباره طبلی و درباره شهری؛ اما رمانی است درباره همه‌مان."),
            StoryParagraph("It is a novel about Germany, but it is also a novel about every country that has ever committed crimes and then tried to forget them.", "رمانی است درباره آلمان، اما رمانی است درباره هر کشوری که هرگز جنایاتی مرتکب شده و بعد تلاش کرده فراموششان کند."),
            StoryParagraph("It is a novel about the twentieth century, but it is also a novel about the twenty-first, because the forces that Grass described — nationalism, hatred, amnesia — have not disappeared.", "رمانی است درباره قرن بیستم، اما رمانی است درباره قرن بیست و یکم هم، زیرا نیروهایی که گراس توصیف کرد — ناسیونالیسم، نفرت، فراموشی — ناپدید نشده‌اند."),
            StoryParagraph("They are still with us; they are always with us; and we must be ready, like Oskar, to drum against them.", "هنوز با ما هستند؛ همیشه با ما هستند؛ و باید آماده باشیم، همچون اسکار، علیه آن‌ها طبل بزنیم."),
            StoryParagraph("The novel has been called obscene, blasphemous, pornographic, and unpatriotic; it has been banned in some countries, condemned by some critics, and misunderstood by many readers.", "رمان فحشا خوانده شده، کفر، پورنوگرافیک و غیرمیهن‌پرستانه؛ در برخی کشورها ممنوع شده، توسط برخی منتقدان محکوم شده و توسط بسیاری خوانندگان بدفهمیده شده."),
            StoryParagraph("But it has also been called a masterpiece, a classic, a work of genius; it won the Nobel Prize for its author, and it has been translated into dozens of languages.", "اما شاهکار هم خوانده شده، کلاسیک، اثری از نابغه؛ جایزه نوبل برای نویسنده‌اش برد و به ده‌ها زبان ترجمه شده."),
            StoryParagraph("Both of these responses are correct, in a sense; the novel is both obscene and sacred, both blasphemous and holy, both pornographic and profound.", "هر دو این پاسخ‌ها به نوعی درست است؛ رمان هم فحشا است و هم مقدس، هم کفر و هم مقدس، هم پورنوگرافیک و هم عمیق."),
            StoryParagraph("Because life itself is both obscene and sacred, both blasphemous and holy, both pornographic and profound; and the novel reflects life.", "زیرا خود زندگی هم فحشا است و هم مقدس، هم کفر و هم مقدس، هم پورنوگرافیک و هم عمیق؛ و رمان زندگی را بازتاب می‌دهد."),
            StoryParagraph("Grass wrote the novel over several years, in Paris and in Germany, in the aftermath of the war, in the middle of the economic miracle.", "گراس رمان را در طول چندین سال نوشت، در پاریس و آلمان، در پس‌آیند جنگ، در میانه معجزه اقتصادی."),
            StoryParagraph("He wrote it for himself, first of all, because he needed to tell his story; he wrote it for his generation, because they needed to remember.", "نخست از همه برای خودش نوشت، چون به گفتن داستانش نیاز داشت؛ برای نسلش نوشت، چون به یاد آوردن نیاز داشتند."),
            StoryParagraph("And he wrote it for us, for the generations that came after, because we need to know what happened, because we need to remember what they tried to forget.", "و برای ما نوشت، برای نسل‌هایی که بعد آمدند، چون باید بدانیم چه اتفاقی افتاد، چون باید به یاد بیاوریم آنچه تلاش کردند فراموش کنند."),
            StoryParagraph("The Tin Drum is a gift to the future: a warning, a memory, a drum.", "طبل حلبی هدیه‌ای به آینده است: هشداری، خاطره‌ای، طبلی."),
            StoryParagraph("And it is a gift that we must accept, whether we want to or not, because the future is coming, and the past is still with us, and the drum is still beating.", "و هدیه‌ای است که باید بپذیریم، خواه بخواهیم خواه نخواهیم، چون آینده می‌آید و گذشته هنوز با ماست و طبل هنوز می‌کوبد."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story of Oskar Matzerath is not finished; it is being told, every day, by every witness, in every life that has been shaped by history.", "زیرا داستان اسکار ماتسرات تمام نشده؛ هر روز گفته می‌شود، توسط هر شاهد، در هر زندگی‌ای که توسط تاریخ شکل گرفته."),
            StoryParagraph("And it will not be finished until we have learned to remember, and to tell the truth, and to drum.", "و تمام نمی‌شود تا وقتی یاد گرفته باشیم به یاد بیاوریم، حقیقت را بگوییم، طبل بزنیم."),
            StoryParagraph("So let us drum, then.", "پس بیایید طبل بزنیم."),
            StoryParagraph("Let us drum for the dead, and for the living, and for the world.", "برای مردگان طبل بزنیم و برای زندگان و برای جهان."),
            StoryParagraph("Let us drum until the truth is heard.", "طبل بزنیم تا حقیقت شنیده شود."),
            StoryParagraph("Let us drum until the drum is silenced, which is to say, never.", "طبل بزنیم تا طبل ساکت شود، یعنی هرگز.")
        )
    )
}